import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.reduce.js";
import AppLayout from "@/components/AppLayout.vue";
import request from "@/utils/axios"; // 导入axios实例
import * as ElementPlusIconsVue from "@element-plus/icons-vue";
export default {
  name: "ReportsView",
  components: {
    AppLayout,
    ...ElementPlusIconsVue
  },
  data() {
    return {
      activeTab: "list",
      loading: false,
      personalRecordsLoading: false,
      reports: [],
      selectedReports: [],
      personalRecords: [],
      personalStats: {
        todayNum: 0,
        total: 0
      },
      filterForm: {
        dateRange: [],
        diseaseType: "",
        confidenceRange: [0, 100]
      },
      diseaseOptions: [{
        value: "糖尿病视网膜病变",
        label: "糖尿病视网膜病变"
      }, {
        value: "青光眼",
        label: "青光眼"
      }, {
        value: "白内障",
        label: "白内障"
      }, {
        value: "AMD",
        label: "AMD"
      }, {
        value: "高血压视网膜病变",
        label: "高血压视网膜病变"
      }, {
        value: "近视",
        label: "近视"
      }, {
        value: "其他疾病/异常",
        label: "其他疾病/异常"
      }, {
        value: "正常",
        label: "正常"
      }],
      pageSize: 10,
      currentPage: 1,
      tableHeight: 500,
      totalReports: 0,
      queryParams: {
        beginTime: "",
        endTime: "",
        diagnosisType: "",
        page: 1,
        pageSize: 10
      },
      personalPageSize: 10,
      personalCurrentPage: 1,
      personalTotal: 0,
      collapsedDays: {},
      dateShortcuts: [{
        text: "最近一周",
        value: () => {
          const end = new Date();
          const start = new Date();
          start.setTime(start.getTime() - 3600 * 1000 * 24 * 7);
          return [this.formatDateString(start), this.formatDateString(end)];
        }
      }, {
        text: "最近一个月",
        value: () => {
          const end = new Date();
          const start = new Date();
          start.setMonth(start.getMonth() - 1);
          return [this.formatDateString(start), this.formatDateString(end)];
        }
      }, {
        text: "最近三个月",
        value: () => {
          const end = new Date();
          const start = new Date();
          start.setMonth(start.getMonth() - 3);
          return [this.formatDateString(start), this.formatDateString(end)];
        }
      }, {
        text: "最近半年",
        value: () => {
          const end = new Date();
          const start = new Date();
          start.setMonth(start.getMonth() - 6);
          return [this.formatDateString(start), this.formatDateString(end)];
        }
      }, {
        text: "最近一年",
        value: () => {
          const end = new Date();
          const start = new Date();
          start.setFullYear(start.getFullYear() - 1);
          return [this.formatDateString(start), this.formatDateString(end)];
        }
      }],
      isFiltered: false
    };
  },
  computed: {
    filteredReports() {
      return this.reports;
    },
    groupedReports() {
      // 按日期分组报告
      const groups = {};
      this.reports.forEach(report => {
        const date = new Date(report.diagnosisTime).toLocaleDateString();
        if (!groups[date]) {
          groups[date] = [];
        }
        groups[date].push(report);
      });

      // 按日期降序排序
      return Object.keys(groups).sort((a, b) => new Date(b) - new Date(a)).reduce((obj, key) => {
        obj[key] = groups[key];
        return obj;
      }, {});
    }
  },
  watch: {
    activeTab(newValue) {
      if (newValue === "timeline") {
        this.$nextTick(() => {
          this.initializeCollapsedDays();
        });
      }
    }
  },
  methods: {
    formatConfidence(val) {
      return val + "%";
    },
    async applyFilter() {
      this.currentPage = 1;
      this.loading = true;

      // 设置查询参数
      if (this.filterForm.dateRange && this.filterForm.dateRange.length === 2) {
        // 格式化日期为API所需的格式（YYYY-MM-DD）
        const startDate = this.filterForm.dateRange[0];
        const endDate = this.filterForm.dateRange[1];
        this.queryParams.beginTime = startDate;
        this.queryParams.endTime = endDate;
      } else {
        this.queryParams.beginTime = "";
        this.queryParams.endTime = "";
      }
      this.queryParams.diagnosisType = this.filterForm.diseaseType || "";
      this.queryParams.page = this.currentPage;
      this.queryParams.pageSize = this.pageSize;
      await this.fetchDiagnosisRecords();

      // 检查筛选后的记录数量
      if (this.reports.length === 0) {
        this.$message.warning("没有找到符合条件的记录，请调整筛选条件");
      } else {
        this.$message.success(`找到 ${this.totalReports} 条符合条件的记录`);
      }
      this.isFiltered = true;
    },
    resetFilter() {
      this.fetchAllRecords();
      this.isFiltered = false;
    },
    handleSelectionChange(selection) {
      this.selectedReports = selection;
    },
    async handleSizeChange(size) {
      this.pageSize = size;
      this.queryParams.pageSize = size;
      this.currentPage = 1;
      this.queryParams.page = 1;
      await this.fetchDiagnosisRecords();
    },
    async handleCurrentChange(page) {
      this.currentPage = page;
      this.queryParams.page = page;
      await this.fetchDiagnosisRecords();
    },
    viewReportDetail(report) {
      this.$router.push(`/reports/detail/${report.patientId}`);
    },
    exportReport(report) {
      this.$message.success(`报告 ${report.id} 已导出为PDF文件`);
    },
    batchExport() {
      this.$message.success(`已导出 ${this.selectedReports.length} 份报告`);
    },
    batchArchive() {
      this.$confirm("确定要归档选中的报告吗?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        this.$message.success(`已归档 ${this.selectedReports.length} 份报告`);
        // 从列表中移除已归档的报告
        const ids = this.selectedReports.map(report => report.id);
        this.reports = this.reports.filter(report => !ids.includes(report.id));
        this.selectedReports = [];
      }).catch(() => {
        // 取消操作
      });
    },
    getTagType(diagnosis) {
      // 根据诊断结果返回不同的标签类型
      switch (diagnosis) {
        case "正常":
          return "success";
        case "糖尿病视网膜病变":
        case "青光眼":
        case "AMD":
          return "danger";
        case "白内障":
        case "高血压视网膜病变":
          return "warning";
        case "近视":
          return "info";
        default:
          return "";
      }
    },
    // 调整表格高度
    adjustTableHeight() {
      this.tableHeight = window.innerHeight - 350; // 根据页面其他元素高度调整
    },
    // 获取诊断记录数据
    async fetchDiagnosisRecords() {
      this.loading = true;
      try {
        // 仅在开发环境下打印调试信息
        if (process.env.NODE_ENV === "development") {
          console.log("Fetching diagnosis records with params:", this.queryParams);
        }
        const response = await request({
          method: "get",
          url: "/diagnosisrecord/show/page",
          params: this.queryParams
        });
        if (response.code === 1) {
          // 更新数据
          this.reports = this.formatReports(response.data.records || []);
          this.totalReports = response.data.total || 0;

          // 如果当前是时间轴视图，更新折叠状态
          if (this.activeTab === "timeline") {
            this.$nextTick(() => {
              this.initializeCollapsedDays();
            });
          }
        } else {
          this.$message.error(response.msg || "获取诊断记录失败");
        }
      } catch (error) {
        console.error("获取诊断记录出错:", error);
        this.$message.error("获取诊断记录失败，请稍后重试");
      } finally {
        this.loading = false;
      }
    },
    // 重置筛选条件并获取所有记录
    async fetchAllRecords() {
      // 重置查询参数为默认值
      this.queryParams = {
        beginTime: "",
        endTime: "",
        diagnosisType: "",
        page: 1,
        pageSize: this.pageSize
      };

      // 重置筛选表单
      this.filterForm = {
        dateRange: [],
        diseaseType: "",
        confidenceRange: [0, 100]
      };

      // 重置筛选状态
      this.isFiltered = false;

      // 获取所有记录
      await this.fetchDiagnosisRecords();
    },
    // 格式化报告数据，增加计算属性和UI所需字段
    formatReports(records) {
      return records.map(record => {
        // 处理置信度，将0-1范围转换为0-100
        const leftConfidence = record.leftConfidence ? Math.round(record.leftConfidence * 100) : 0;
        const rightConfidence = record.rightConfidence ? Math.round(record.rightConfidence * 100) : 0;
        return {
          ...record,
          leftEye: {
            diagnosis: record.leftResult || "",
            confidence: leftConfidence
          },
          rightEye: {
            diagnosis: record.rightResult || "",
            confidence: rightConfidence
          },
          finalDiagnosis: record.finalResult || "",
          time: record.diagnosisTime,
          // 保持兼容性
          patientId: record.patientId || record.id // 确保patientId存在
        };
      });
    },
    formatTime(timeString) {
      if (!timeString) return "";
      try {
        const date = new Date(timeString);
        if (isNaN(date.getTime())) return timeString; // Return original if invalid

        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");
        const hours = String(date.getHours()).padStart(2, "0");
        const minutes = String(date.getMinutes()).padStart(2, "0");
        const seconds = String(date.getSeconds()).padStart(2, "0");
        return `${year}/${month}/${day} ${hours}:${minutes}:${seconds}`;
      } catch (error) {
        console.error("Error formatting time:", error);
        return timeString; // Return original on error
      }
    },
    // 获取个人诊断记录
    async fetchPersonalDiagnosisRecords() {
      this.personalRecordsLoading = true;
      try {
        const doctorId = localStorage.getItem("doctorId") || "";
        const response = await request({
          method: "get",
          url: "/diagnosisrecord/show/me",
          params: {
            doctorId: doctorId,
            page: this.personalCurrentPage,
            pageSize: this.personalPageSize
          }
        });
        if (response.code === 1) {
          // 更新数据
          this.personalRecords = response.data.records || [];
          this.personalStats = {
            todayNum: response.data.todayNum || 0,
            total: response.data.total || 0
          };
          this.personalTotal = response.data.total || 0;
        } else {
          this.$message.error(response.msg || "获取个人诊断记录失败");
        }
      } catch (error) {
        console.error("获取个人诊断记录出错:", error);
        this.$message.error("获取个人诊断记录失败，请稍后重试");
      } finally {
        this.personalRecordsLoading = false;
      }
    },
    handlePersonalSizeChange(size) {
      this.personalPageSize = size;
      this.personalCurrentPage = 1; // Reset to first page when changing page size
      this.fetchPersonalDiagnosisRecords();
    },
    handlePersonalPageChange(page) {
      this.personalCurrentPage = page;
      this.fetchPersonalDiagnosisRecords();
    },
    toggleCollapseDay(date) {
      this.collapsedDays[date] = !this.collapsedDays[date];
    },
    getTimelineItemClass(report) {
      // Get diagnosis type for styling
      const leftDiagnosis = report.leftResult || report.leftEye?.diagnosis || "";
      const rightDiagnosis = report.rightResult || report.rightEye?.diagnosis || "";

      // Determine class based on diagnosis severity
      if (leftDiagnosis.includes("AMD") || rightDiagnosis.includes("AMD") || leftDiagnosis.includes("糖尿病") || rightDiagnosis.includes("糖尿病") || leftDiagnosis.includes("青光眼") || rightDiagnosis.includes("青光眼")) {
        return "diagnosis-severe";
      } else if (leftDiagnosis.includes("白内障") || rightDiagnosis.includes("白内障") || leftDiagnosis.includes("高血压") || rightDiagnosis.includes("高血压")) {
        return "diagnosis-moderate";
      } else if (leftDiagnosis.includes("近视") || rightDiagnosis.includes("近视") || leftDiagnosis.includes("其他") || rightDiagnosis.includes("其他")) {
        return "diagnosis-mild";
      } else if (leftDiagnosis.includes("正常") && rightDiagnosis.includes("正常")) {
        return "diagnosis-normal";
      }
      return "";
    },
    // 初始化折叠状态
    initializeCollapsedDays() {
      // 设置所有日期为展开状态
      const collapsedState = {};
      Object.keys(this.groupedReports).forEach(date => {
        collapsedState[date] = false;
      });
      this.collapsedDays = collapsedState;
    },
    // 将日期格式化为YYYY-MM-DD
    formatDateString(date) {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, "0");
      const day = String(date.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    }
  },
  async mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 调整表格高度
    this.adjustTableHeight();
    window.addEventListener("resize", this.adjustTableHeight);

    // 初始化时获取所有数据
    await this.fetchAllRecords();
    await this.fetchPersonalDiagnosisRecords(); // 获取个人诊断记录

    // 初始化折叠状态
    this.initializeCollapsedDays();
  },
  beforeUnmount() {
    window.removeEventListener("resize", this.adjustTableHeight);
  }
};
